floor_fn:
"""Test whether access to the cloudformation template bucket is required.

    Args:
        outline: The outline action.
        dump: The dump action.

    Returns:
        If access to CF bucket is needed, return True.

    """
def should_ensure_cfn_bucket(outline: bool, dump: bool) -> bool {
    return (not outline and not dump);
}

test_blocks:
test "t0" {
    assert (should_ensure_cfn_bucket(True, False) == False);;
}

test "t1" {
    assert (should_ensure_cfn_bucket(False, False) == True);;
}

test "t2" {
    assert (should_ensure_cfn_bucket(False, True) == False);;
}

test "t3" {
    assert (should_ensure_cfn_bucket(True, True) == False);;
}
